    def _init_database_search(self):
        """Initialize database search functionality"""
        try:
            print("[Info] Initializing database search...")
            
            # Import with detailed error reporting
            try:
                from ui.database_search_integration import DatabaseSearchIntegration
                print("[Info] DatabaseSearchIntegration imported successfully")
            except ImportError as ie:
                print(f"[Error] Failed to import DatabaseSearchIntegration: {ie}")
                return
            
            from PyQt5.QtWidgets import QShortcut
            from PyQt5.QtGui import QKeySequence
            
            # Create database search integration
            self.db_search_integration = DatabaseSearchIntegration(self)
            print("[Info] DatabaseSearchIntegration instance created")
            
            # Create shortcut for database search (Ctrl+Shift+F)
            self.db_search_shortcut = QShortcut(QKeySequence("Ctrl+Shift+F"), self.main_window)
            self.db_search_shortcut.activated.connect(self._show_database_search)
            
            print("[Info] Database search initialized - Press Ctrl+Shift+F to search")
        except Exception as e:
            print(f"[Error] Failed to initialize database search: {str(e)}")
            import traceback
            traceback.print_exc()
    
    def _init_eye_assistant(self):
        """Initialize EYE AI Assistant functionality"""
        try:
            print("[Info] Initializing EYE AI Assistant...")
            
            # Import QShortcut and QKeySequence
            from PyQt5.QtWidgets import QShortcut
            from PyQt5.QtGui import QKeySequence
            
            # Create shortcut for EYE AI Assistant (Ctrl+Shift+E)
            self.eye_assistant_shortcut = QShortcut(QKeySequence("Ctrl+Shift+E"), self.main_window)
            self.eye_assistant_shortcut.activated.connect(self._show_eye_assistant)

            # Create shortcut for User Behavior Analytics (Ctrl+Shift+B)
            self.uba_shortcut = QShortcut(QKeySequence("Ctrl+Shift+B"), self.main_window)
            self.uba_shortcut.activated.connect(self.open_uba_dialog)
            
            # Initialize eye_tab as None (will be created on first use)
            self.eye_tab = None
            
            print("[Info] EYE AI Assistant initialized - Press Ctrl+Shift+E to open")
        except Exception as e:
            print(f"[Error] Failed to initialize EYE AI Assistant: {str(e)}")
            import traceback
            traceback.print_exc()
    

    
    def _show_database_search(self):
        """Show database search dialog"""
        try:
            # Check if a case is loaded
            if not hasattr(self, 'case_paths') or not self.case_paths:
                QtWidgets.QMessageBox.warning(
                    self.main_window,
                    "No Case Loaded",
                    "Please open or create a case before using database search.\n\n"
                    "Use 'Create case' or 'Open case' buttons to get started."
                )
                return
            
            # Check if artifacts directory exists
            artifacts_dir = self.case_paths.get('artifacts_dir')
            if not artifacts_dir or not os.path.exists(artifacts_dir):
                QtWidgets.QMessageBox.warning(
                    self.main_window,
                    "No Artifacts Directory",
                    "The case artifacts directory does not exist.\n\n"
                    "Please collect forensic artifacts first."
                )
                return
            
            print("[Info] Opening database search dialog...")
            if hasattr(self, 'db_search_integration'):
                # Get artifacts directory from case_paths (where databases are stored)
                case_directory = self.case_paths.get('artifacts_dir', '')
                self.db_search_integration.show_search_dialog(case_directory)
            else:
                print("[Error] Database search integration not initialized")
                QtWidgets.QMessageBox.warning(
                    self.main_window,
                    "Database Search",
                    "Database search is not available. Please check the console for errors."
                )
        except Exception as e:
            print(f"[Error] Failed to show database search: {str(e)}")
            import traceback
            traceback.print_exc()
            QtWidgets.QMessageBox.critical(
                self.main_window,
                "Database Search Error",
                f"An error occurred:\n{str(e)}"
            )

    def _show_eye_assistant(self):
        """Show Eye AI Forensic Assistant Window.

        The actual Eye window load is heavy on first click (PyQt WebEngine
        process spin-up + React bundle load takes ~1-3 s). We surface a
        lightweight native splash IN THE SAME EVENT-LOOP TICK so the user
        sees visible feedback immediately and cannot mistake the delay for
        a crash. The native splash uses only QPixmap + QLabel — no
        WebEngine — so it paints in well under 100 ms even cold.
        """
        instant_splash = None
        try:
            # ---- 1. Instant visual feedback (paints same second as the click) ----
            instant_splash = self._build_eye_instant_splash()
            if instant_splash is not None:
                instant_splash.show()
                instant_splash.raise_()
                # Force Qt to render the splash before we touch anything heavy.
                instant_splash.repaint()
                QtWidgets.QApplication.processEvents(
                    QtCore.QEventLoop.ExcludeUserInputEvents, 50
                )

            # ---- 2. Resolve case context (cheap) ----
            artifacts_dir = None
            if hasattr(self, 'case_paths') and self.case_paths:
                artifacts_dir = self.case_paths.get('case_root')
            QtWidgets.QApplication.processEvents(
                QtCore.QEventLoop.ExcludeUserInputEvents, 25
            )

            # ---- 3. Heavy work (WebEngine init, EYE window build, React load) ----
            # Hand the instant splash to EYEWindowManager so it can be torn
            # down at the right moment — after the real Eye window is on
            # screen but BEFORE start_session opens the case-setup modal.
            # Otherwise the instant splash stays painted behind the modal for
            # the entire duration the user spends filling it in.
            from eye.ui.eye_window_manager import EYEWindowManager
            self.eye_tab = EYEWindowManager.show_assistant(
                main_window=self.main_window,
                artifacts_dir=artifacts_dir,
                parent_splash=instant_splash,
            )
            # show_assistant has already destroyed the splash; don't double-close.
            instant_splash = None
            print("[Eye AI] Window launched successfully")

        except Exception as e:
            import traceback
            traceback.print_exc()
            QtWidgets.QMessageBox.critical(
                self.main_window,
                "Eye AI Error",
                f"An error occurred while launching Eye AI:\n{str(e)}"
            )
        finally:
            # Defensive: if show_assistant didn't take ownership (e.g. an
            # exception fired before it could destroy the splash), tear it
            # down here.
            if instant_splash is not None:
                try:
                    instant_splash.close()
                    instant_splash.deleteLater()
                except Exception:
                    pass

    def _build_eye_instant_splash(self):
        """Build a lightweight native splash for the Eye AI launch path.

        Uses only QWidget + QPainter so it paints in the same event-loop tick
        the user clicked the button. No WebEngine, no HTML load. Styling
        matches `eye/ui/eye_splash.html` (purple #a855f7 accent, cyan #22d3ee
        secondary, dark #0f1017 card, indigo→purple→cyan gradient stripe,
        Eye logo with rotating ring, indeterminate progress bar).
        Returns None if the splash cannot be built (never raises).
        """
        try:
            base_dir = os.path.dirname(os.path.abspath(__file__))
            logo_path = os.path.join(
                base_dir, "GUI Resources", "the Eye AI agent transparent.png"
            )
            return _EyeInstantSplash(logo_path=logo_path, parent=self.main_window)
        except Exception as e:
            print(f"[Eye AI] Instant splash unavailable: {e}")
            return None

    def get_app_config_dir(self):
        """Get the configuration and default case directories"""
        app_dir = os.path.dirname(os.path.abspath(__file__))
        config_dir = os.path.join(app_dir, 'config')
        os.makedirs(config_dir, exist_ok=True)
        # Use user's Documents\CrowEye as default cases root if available, fallback to current directory
        user_docs = os.path.join(os.path.expanduser('~'), 'Documents', 'CrowEye')
        default_dir = user_docs if os.path.isdir(os.path.dirname(user_docs)) else os.path.dirname(os.path.abspath(__file__))
        os.makedirs(default_dir, exist_ok=True)
        return config_dir, default_dir

    def save_last_case(self, case_config):
        """Persist the last opened/created case info."""
        config_dir, _ = self.get_app_config_dir()
        last_case_path = os.path.join(config_dir, 'last_case.json')
        try:
            with open(last_case_path, 'w') as f:
                json.dump(case_config, f, indent=4)
        except Exception as e:
            print(f"[Error] Failed to save last case: {str(e)}")

    def load_last_case(self):
        """Load the last used case by delegating to open_case()."""
        config_dir, _ = self.get_app_config_dir()
        last_case_file = os.path.join(config_dir, 'last_case.json')
        if not os.path.exists(last_case_file):
            return False
        try:
            with open(last_case_file, 'r') as f:
                case_config = json.load(f)
            directory_path = case_config.get('paths', {}).get('case_root')
            if not directory_path or not os.path.exists(directory_path):
                return False
            self.open_case(directory_path)
            return True
        except Exception as e:
            print(f"[Error] Failed to load last case: {str(e)}")
            return False

    def open_case(self, directory_path=None):
        """Open and load a case.
        If directory_path is None, prompt the user to pick a directory.
        """
        # Ask for directory if not provided
        config_dir, default_cases_dir = self.get_app_config_dir()
        if directory_path is None:
            directory_path = QFileDialog.getExistingDirectory(
                self.main_window,
                "Select Case Directory",
                default_cases_dir,
                QFileDialog.ShowDirsOnly
            )
            if not directory_path:
                return None

        try:
            # Clear any existing data from tables and ensure DB connections are closed
            try:
                self.clear_all_tables()
            except Exception:
                pass
            try:
                self.close_all_database_connections()
            except Exception:
                pass
            # Ensure artifacts directory exists
            artifacts_dir = os.path.join(directory_path, "Target_Artifacts")
            os.makedirs(artifacts_dir, exist_ok=True)
            
            # Create live_acquisition directory for raw collected artifacts
            live_acquisition_path = os.path.join(directory_path, "live_acquisition")
            os.makedirs(live_acquisition_path, exist_ok=True)
            print(f"[Open Case] Using live_acquisition for raw artifacts: {live_acquisition_path}")
            print(f"[Open Case] Using Target_Artifacts for parsed databases: {artifacts_dir}")
            print(f"[Open Case] Created default live_acquisition directory: {live_acquisition_path}")
            
            # Store paths
            self.case_paths = {
                'case_root': directory_path,
                'artifacts_dir': artifacts_dir,
                'live_acquisition_dir': live_acquisition_path,
                'c_ajl_lnk_dir': os.path.join(artifacts_dir, "C_AJL_Lnk"),
                'registry_dir': os.path.join(artifacts_dir, "Registry_Hives"),
                'prefetch_dir': os.path.join(artifacts_dir, "Prefetch"),
                'mft_dir': os.path.join(artifacts_dir, "MFT"),
                'usn_dir': os.path.join(artifacts_dir, "USN_Journal"),
                'databases': {
                    'registry': os.path.join(artifacts_dir, 'registry_data.db'),
                    'lnk': os.path.join(artifacts_dir, 'LnkDB.db'),
                    'logs': os.path.join(artifacts_dir, 'Log_Claw.db'),
                    'prefetch': os.path.join(artifacts_dir, 'prefetch_data.db'),
                    'shimcache': os.path.join(artifacts_dir, 'shimcache.db'),
                    'amcache': os.path.join(artifacts_dir, 'amcache.db'),
                    'recyclebin': os.path.join(artifacts_dir, 'recyclebin_analysis.db'),
                    'srum': os.path.join(artifacts_dir, 'srum_data.db'),
                    'mft': os.path.join(artifacts_dir, 'mft_claw_analysis.db'),
                    'usn': os.path.join(artifacts_dir, 'USN_journal.db'),
                    'mft_usn_correlated': os.path.join(artifacts_dir, 'mft_usn_correlated_analysis.db')
                }
            }
            # Create directories (excluding databases dictionary)
            for key, path in self.case_paths.items():
                if key != 'databases' and isinstance(path, str):
                    os.makedirs(path, exist_ok=True)
            # Update UI
            case_name = os.path.basename(directory_path)
            self.label.setText(f"Case: {case_name}")
            
            # Enable Parse Offline Artifacts button when case is opened
            if hasattr(self, 'ParseOfflineArtifactsButton'):
                self.ParseOfflineArtifactsButton.setEnabled(True)
            
            # Add/update case in history
            if hasattr(self, 'case_history_manager') and self.case_history_manager:
                try:
                    # Check if case exists in history
                    existing_case = self.case_history_manager.get_case_by_path(directory_path)
                    if existing_case:
                        # Update access time
                        self.case_history_manager.update_case_access(directory_path)
                        print(f"[Config] Updated access time for case: {case_name}")
                    else:
                        # Add new case to history
                        case_info = {
                            'name': case_name,
                            'path': directory_path,
                            'description': ''
                        }
                        self.case_history_manager.add_case(case_info)
                        print(f"[Config] Added case to history: {case_name}")
                except Exception as e:
                    print(f"[Config] Failed to update case history: {e}")
            
            # Save case config and mark as last
            case_config = {
                'case_name': case_name,
                'opened_date': datetime.datetime.now().isoformat(),
                'paths': self.case_paths,
                'databases': {
                    'registry': os.path.join(self.case_paths['artifacts_dir'], 'registry_data.db'),
                    'lnk': os.path.join(self.case_paths['artifacts_dir'], 'LnkDB.db'),
                    'logs': os.path.join(self.case_paths['artifacts_dir'], 'Log_Claw.db'),
                    'prefetch': os.path.join(self.case_paths['artifacts_dir'], 'prefetch_data.db'),
                    'shimcache': os.path.join(self.case_paths['artifacts_dir'], 'shimcache.db'),
                    'amcache': os.path.join(self.case_paths['artifacts_dir'], 'amcache.db'),
                    'recyclebin': os.path.join(self.case_paths['artifacts_dir'], 'recyclebin_analysis.db'),
                    'srum': os.path.join(self.case_paths['artifacts_dir'], 'srum_data.db'),
                    'mft': os.path.join(self.case_paths['artifacts_dir'], 'mft_claw_analysis.db'),
                    'usn': os.path.join(self.case_paths['artifacts_dir'], 'USN_journal.db'),
                    'mft_usn_correlated': os.path.join(self.case_paths['artifacts_dir'], 'mft_usn_correlated_analysis.db')
                }
            }
            config_path = os.path.join(config_dir, f"case_{case_name}.json")
            with open(config_path, 'w') as f:
                json.dump(case_config, f, indent=4)
            self.save_last_case(case_config)
            
            # Detect Windows partition for the case
            print("[Open Case] Detecting Windows partition...")
            try:
                # Check if partition is already configured
                if 'windows_partition' not in case_config:
                    # Detect and store Windows partition
                    detected_partition = self.detect_and_set_windows_partition(offline_mode=False)
                    if detected_partition:
                        print(f"[Open Case] Windows partition detected: {detected_partition}")
                        # Persist it so the next open reuses it instead of re-detecting.
                        try:
                            case_config['windows_partition'] = detected_partition
                            with open(config_path, 'w') as f:
                                json.dump(case_config, f, indent=4)
                        except Exception as e:
                            print(f"[Open Case] Could not persist windows_partition: {e}")
                    else:
                        print("[Open Case] Windows partition detection failed, defaulting to C:")
                else:
                    print(f"[Open Case] Using configured Windows partition: {case_config['windows_partition']}")
            except Exception as e:
                print(f"[Open Case] Error during partition detection: {e}")
                print("[Open Case] Defaulting to C: partition")
        
            # Note: Eye AI Assistant initialization is deferred until manual launch
            # to prevent UI collision with the case loading progress dialog.
            self.eye_tab = None

            # Check if this is a new case (no database files exist yet)
            db_files_exist = any(os.path.exists(db_path) for db_path in case_config['databases'].values())
        
            if not db_files_exist:
                # New / empty case: no parsed databases exist yet, so there is
                # nothing to load. Tables were already cleared at the top of
                # open_case, so the UI is in a clean empty state — calling
                # load_all_data here would only flood the console with
                # "no such table" / "database not found" errors. Just open it
                # empty; data loads once the user collects/parses artifacts.
                print(f"[Open Case] New / empty case detected, opening without load: {case_name}")

                # Show informational message about empty case
                QMessageBox.information(
                    self.main_window,
                    "Empty Case",
                    f"Case '{case_name}' has been opened successfully.\n\n"
                    "This case doesn't have any collected data yet.\n\n"
                    "Collect from a live machine or import artifacts — they'll load automatically."
                )
            else:
                # For existing cases, load the existing data. Call load_all_data
                # directly — it owns its own loading dialog (with working Cancel +
                # accurate completion); routing it through run_analysis_with_loading
                # would stack a second dialog and flash "completed" even on cancel.
                print(f"[Open Case] Loading existing case data for: {case_name}")
                self.load_all_data()
        
            # Note: Eye AI Assistant initialization is deferred until manual launch
            # (Ctrl+Shift+E) to prevent UI clutter.
            self.eye_tab = None
        
            print(f"[Open Case] Successfully opened case: {case_name}")
            return self.case_paths
        except Exception as e:
            QMessageBox.critical(
                self.main_window,
                "Error",
                f"Failed to open case:\n{str(e)}"
            )
            return None

    def animate_progress_bar(self, progress_bar):
        """Animate the progress bar to make it more visible"""
        # For indeterminate progress bars, we can change the text to show activity
        current_text = progress_bar.text()
        if not current_text:
            progress_bar.setText("Processing")
        elif current_text == "Processing":
            progress_bar.setText("Processing.")
        elif current_text == "Processing.":
            progress_bar.setText("Processing..")
        elif current_text == "Processing..":
            progress_bar.setText("Processing...")
        else:
            progress_bar.setText("Processing")

    def load_case_config(self, case_name):
        """Load case configuration from file"""
        config_dir, _ = self.get_app_config_dir() # Get config dir only
        config_path = os.path.join(config_dir, f"case_{case_name}.json")
        
        try:
            with open(config_path, 'r') as config_file:
                return json.load(config_file)
        except Exception as e:
            QMessageBox.critical(
                self.main_window,
                "Error",
                f"Failed to load case configuration:\n{str(e)}"
            )
            return None
            
    def save_case_config(self):
        """Save current case configuration to file"""
        if not hasattr(self, 'case_paths') or not self.case_paths:
            print("[Warning] No case paths available to save configuration")
            return
            
        case_name = os.path.basename(self.case_paths.get('case_root', ''))
        if not case_name:
            print("[Warning] Invalid case name, cannot save configuration")
            return
            
        config_dir, _ = self.get_app_config_dir() # Get config dir only
        config_path = os.path.join(config_dir, f"case_{case_name}.json")
        
        try:
            # Load existing config first
            with open(config_path, 'r') as config_file:
                case_config = json.load(config_file)
                
            # Update the config with current paths and databases
            case_config['paths'] = self.case_paths
            
            # Write back the updated config
            with open(config_path, 'w') as config_file:
                json.dump(case_config, config_file, indent=4)
                
            # Update last case file
            self.save_last_case(case_config)
            print(f"[Info] Case configuration saved for: {case_name}")
        except Exception as e:
            print(f"[Error] Failed to save case configuration: {str(e)}")
            return None

    def get_windows_partition(self) -> str:
        """
        Get Windows partition letter for the current case.
        
        Returns:
            str: Windows partition letter (e.g., "C:") or "C:" as default
        """
        # Check if case configuration exists
        if not hasattr(self, 'case_paths') or not self.case_paths:
            print("[Warning] No active case, defaulting to C: partition")
            return "C:"
        
        case_name = os.path.basename(self.case_paths.get('case_root', ''))
        if not case_name:
            print("[Warning] Invalid case name, defaulting to C: partition")
            return "C:"
        
        # Try to load from case configuration file
        try:
            config_dir, _ = self.get_app_config_dir()
            config_path = os.path.join(config_dir, f"case_{case_name}.json")
            
            if os.path.exists(config_path):
                with open(config_path, 'r') as config_file:
                    case_config = json.load(config_file)
                    
                # Get windows_partition from config, default to "C:" if not found
                windows_partition = case_config.get('windows_partition', 'C:')
                print(f"[Info] Windows partition for case '{case_name}': {windows_partition}")
                return windows_partition
            else:
                print(f"[Warning] Case config not found, defaulting to C: partition")
                return "C:"
                
        except Exception as e:
            print(f"[Error] Failed to load Windows partition from config: {e}")
            return "C:"
    
    def set_windows_partition(self, partition: str):
        """
        Set Windows partition letter for the current case.
        
        Args:
            partition: Windows partition letter (e.g., "D:")
        """
        # Validate partition format
        if not partition or len(partition) < 2 or partition[1] != ':':
            print(f"[Error] Invalid partition format: {partition}. Expected format like 'C:'")
            return False
        
        # Check if case configuration exists
        if not hasattr(self, 'case_paths') or not self.case_paths:
            print("[Error] No active case to set Windows partition")
            return False
        
        case_name = os.path.basename(self.case_paths.get('case_root', ''))
        if not case_name:
            print("[Error] Invalid case name, cannot set Windows partition")
            return False
        
        # Update case configuration file
        try:
            config_dir, _ = self.get_app_config_dir()
            config_path = os.path.join(config_dir, f"case_{case_name}.json")
            
            # Load existing config
            if os.path.exists(config_path):
                with open(config_path, 'r') as config_file:
                    case_config = json.load(config_file)
            else:
                # Create new config if doesn't exist
                case_config = {
                    'case_name': case_name,
                    'opened_date': datetime.datetime.now().isoformat(),
                    'paths': self.case_paths
                }
            
            # Update windows_partition field
            case_config['windows_partition'] = partition
            case_config['partition_detection_timestamp'] = datetime.datetime.now().isoformat()
            
            # Save updated config
            with open(config_path, 'w') as config_file:
                json.dump(case_config, config_file, indent=4)
            
            # Update last case file
            self.save_last_case(case_config)
            
            print(f"[Info] Windows partition set to {partition} for case '{case_name}'")
            return True
            
        except Exception as e:
            print(f"[Error] Failed to set Windows partition: {e}")
            return False
    
    def detect_and_set_windows_partition(self, offline_mode: bool = False, 
                                        mounted_partitions: list = None):
        """
        Detect Windows partition and store in case configuration.
        
        Args:
            offline_mode: If True, scan for Windows installations on mounted partitions
            mounted_partitions: List of partition paths to scan (for offline mode)
            
        Returns:
            str: Detected Windows partition letter or None if detection failed
        """
        try:
            from Artifacts_Collectors.windows_partition_detector import WindowsPartitionDetector
            
            detector = WindowsPartitionDetector()
            
            if offline_mode:
                # Offline detection
                print("[Info] Detecting Windows installations on offline disk images...")
                windows_partitions = detector.detect_offline_system(mounted_partitions)
                
                if not windows_partitions:
                    print("[Warning] No Windows installations found")
                    QMessageBox.warning(
                        self.main_window,
                        "No Windows Installation Found",
                        "No Windows installation detected on the specified partitions.\n"
                        "Please verify the disk image is mounted correctly or manually specify the partition."
                    )
                    return None
                
                # Handle multiple installations
                if len(windows_partitions) > 1:
                    selected_partition = detector.prompt_user_selection(windows_partitions)
                else:
                    selected_partition = windows_partitions[0]
                
                # Store in configuration
                self.set_windows_partition(selected_partition)
                return selected_partition
                
            else:
                # Live detection
                print("[Info] Detecting Windows partition on live system...")
                windows_partition = detector.detect_live_system()
                
                # Store in configuration
                self.set_windows_partition(windows_partition)
                return windows_partition
                
        except Exception as e:
            print(f"[Error] Windows partition detection failed: {e}")
            QMessageBox.critical(
                self.main_window,
                "Detection Error",
                f"Failed to detect Windows partition:\n{str(e)}\n\n"
                "Defaulting to C: drive. You can manually override this in case settings."
            )
            # Default to C: on error
            self.set_windows_partition("C:")
            return "C:"

    def clear_all_tables(self):
        """Clear all data from all tables in the application"""
        try:
            print("[System] Clearing all application data...")
            
            # 1. Clear search results first
            self.clear_search_results()
            
            # 2. Find all tables and clear them
            tables = self.find_all_table_widgets()
            for table in tables:
                try:
                    # Clear contents
                    table.setRowCount(0)
                    # Reset sorting if needed
                    table.clearSpans()
                except Exception as e:
                    print(f"[Warning] Failed to clear table {table.objectName()}: {str(e)}")
            
            # 3. Reset internal state variables
            self.case_paths = None
            self.search_results = []
            self.current_result_index = -1
            
            # 4. Reset UI labels
            if hasattr(self, 'label'):
                self.label.setText("Case: None")
            
            # 5. Disable Parse Offline Artifacts button when case is closed
            if hasattr(self, 'ParseOfflineArtifactsButton'):
                self.ParseOfflineArtifactsButton.setEnabled(False)
            
            print("[System] All tables cleared and state reset")
            
        except Exception as e:
            print(f"[Error] Failed to clear tables: {str(e)}")
            import traceback
            traceback.print_exc()
    
