    def _collect_all_live_artifacts(self, case_paths, windows_partition, step_callback, log_callback, cancellation_check):
        """
        Collect all live artifacts (called by LiveAcquisitionWorker).
        
        Bug Fix Task 12.1: Refactored to run in worker thread without blocking GUI.
        
        Args:
            case_paths: Dictionary containing case_root, artifacts_dir, etc.
            windows_partition: Windows partition path (e.g., "C:")
            step_callback: Callback function(step_index, step_message) for progress updates
            log_callback: Callback function(message) for log messages
            cancellation_check: Function that returns True if user cancelled
        """
        try:
            log_callback("[Open Case] Starting full live analysis...")
            
            # Step 0: Initialize
            step_callback(0, "INITIALIZING ARTIFACT COLLECTION")
            log_callback("[Init] Initializing artifact collection system...")
            log_callback("[Init] Case paths configured")
            log_callback("[Init] Ready to collect artifacts")
            
            if cancellation_check():
                return
            
            # Step 1: Registry data (FIRST - most comprehensive)
            step_callback(1, "COLLECTING SYSTEM & USER REGISTRY HIVES")
            step_callback(2, "EXTRACTING DATA FROM THE REGISTRY HIVE")
            try:
                log_callback("[Registry] Collecting live registry data...")
                from Artifacts_Collectors.Regclaw import parse_live_registry
                case_root = case_paths.get('case_root') if case_paths else None
                artifacts_dir = case_paths.get('artifacts_dir') if case_paths else None
                if artifacts_dir:
                    db_path = os.path.join(artifacts_dir, 'registry_data.db')
                else:
                    db_path = None
                parse_live_registry(case_root=case_root, db_path=db_path)
                log_callback("[Registry] Registry data collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[Registry Error] {str(e)}")
                log_callback(f"[Registry Error Details] {error_details}")
                print(f"[Registry Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 3 & 4: LNK and Jump Lists
            step_callback(3, "COLLECTING LNK (SHORTCUT) FILES")
            step_callback(4, "COLLECTING AUTOMATIC & CUSTOM JUMP LISTS")
            log_callback("[LNK] Starting LNK and Jump Lists collection...")
            try:
                from Artifacts_Collectors.A_CJL_LNK_Claw import A_CJL_LNK_Claw
                case_root = case_paths.get('case_root') if case_paths else None
                A_CJL_LNK_Claw(case_path=case_root, offline_mode=False, direct_parse=True)
                log_callback("[LNK] LNK and Jump Lists collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[LNK Error] {str(e)}")
                log_callback(f"[LNK Error Details] {error_details}")
                print(f"[LNK Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 5: Prefetch files
            step_callback(5, "COLLECTING PREFETCH EXECUTION EVIDENCE")
            try:
                log_callback("[Prefetch] Collecting prefetch data...")
                from Artifacts_Collectors.Prefetch_claw import prefetch_claw
                case_root = case_paths.get('case_root') if case_paths else None
                prefetch_claw(case_path=case_root, offline_mode=False, windows_partition=windows_partition)
                log_callback("[Prefetch] Prefetch data collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[Prefetch Error] {str(e)}")
                log_callback(f"[Prefetch Error Details] {error_details}")
                print(f"[Prefetch Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 6: Event logs
            step_callback(6, "COLLECTING WINDOWS EVENT LOGS")
            try:
                log_callback("[Logs] Collecting Windows event logs...")
                from Artifacts_Collectors.WinLog_Claw import main as collect_logs
                case_root = case_paths.get('case_root') if case_paths else None
                collect_logs(case_path=case_root)
                log_callback("[Logs] Event Logs collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[Logs Error] {str(e)}")
                log_callback(f"[Logs Error Details] {error_details}")
                print(f"[Logs Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 7: ShimCache data
            step_callback(7, "COLLECTING SHIMCACHE (APPCOMPATCACHE)")
            try:
                log_callback("[ShimCache] Collecting ShimCache data...")
                from Artifacts_Collectors.shimcash_claw import ShimCacheParser
                case_root = case_paths.get('case_root') if case_paths else None
                artifacts_dir = case_paths.get('artifacts_dir') if case_paths else None
                if artifacts_dir:
                    db_path = os.path.join(artifacts_dir, 'shimcache.db')
                else:
                    db_path = 'shimcache.db'
                parser = ShimCacheParser(db_path)
                parser.run()
                log_callback("[ShimCache] ShimCache data collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[ShimCache Error] {str(e)}")
                log_callback(f"[ShimCache Error Details] {error_details}")
                print(f"[ShimCache Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 8: Amcache data
            step_callback(8, "COLLECTING AMCACHE DATA")
            try:
                log_callback("[Amcache] Collecting Amcache data...")
                from Artifacts_Collectors.amcacheparser import parse_amcache_hive
                case_root = case_paths.get('case_root') if case_paths else None
                artifacts_dir = case_paths.get('artifacts_dir') if case_paths else None
                if artifacts_dir:
                    db_path = os.path.join(artifacts_dir, 'amcache.db')
                else:
                    db_path = 'amcache.db'
                offline_mode = False
                parse_amcache_hive(case_path=case_root, offline_mode=offline_mode, 
                                  db_path=db_path, windows_partition=windows_partition)
                log_callback("[Amcache] Amcache data collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[Amcache Error] {str(e)}")
                log_callback(f"[Amcache Error Details] {error_details}")
                print(f"[Amcache Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 9: RecycleBin data
            step_callback(9, "COLLECTING RECYCLEBIN ARTIFACTS")
            try:
                log_callback("[RecycleBin] Collecting RecycleBin data...")
                from Artifacts_Collectors.recyclebin_claw import parse_recycle_bin
                case_root = case_paths.get('case_root') if case_paths else None
                
                if case_root:
                    db_path = parse_recycle_bin(case_path=case_root)
                else:
                    db_path = parse_recycle_bin()
                    
                log_callback(f"[RecycleBin] RecycleBin data collected successfully, database: {db_path}")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[RecycleBin Error] {str(e)}")
                log_callback(f"[RecycleBin Error Details] {error_details}")
                print(f"[RecycleBin Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 10: SRUM data
            step_callback(10, "COLLECTING SRUM NETWORK & EXECUTION DATA")
            try:
                log_callback("[SRUM] Collecting SRUM data...")
                from Artifacts_Collectors.SRUM_Claw import parse_srum_data
                artifacts_dir = case_paths.get('artifacts_dir') if case_paths else None
                
                if artifacts_dir:
                    result = parse_srum_data(case_artifacts_dir=artifacts_dir, windows_partition=windows_partition)
                    if result.get('success'):
                        log_callback(f"[SRUM] SRUM data collected successfully: {result.get('statistics', {})}")
                    else:
                        log_callback(f"[SRUM] SRUM parsing completed with warnings: {result.get('errors', [])}")
                else:
                    log_callback("[SRUM] No artifacts directory available, skipping SRUM collection")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[SRUM Error] {str(e)}")
                log_callback(f"[SRUM Error Details] {error_details}")
                print(f"[SRUM Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            # Step 11, 12, 13: MFT and USN Journal data
            step_callback(11, "PARSING MASTER FILE TABLE (MFT)")
            step_callback(12, "PARSING USN JOURNAL")
            step_callback(13, "CORRELATING MFT & USN DATA")
            try:
                log_callback("[MFT-USN] Collecting MFT and USN Journal data...")
                self.parse_mft_usn_correlation()
                log_callback("[MFT-USN] MFT and USN Journal data collected successfully")
            except Exception as e:
                import traceback
                error_details = traceback.format_exc()
                log_callback(f"[MFT-USN Error] {str(e)}")
                log_callback(f"[MFT-USN Error Details] {error_details}")
                print(f"[MFT-USN Error] {str(e)}\n{error_details}")
            
            if cancellation_check():
                return
            
            log_callback("[Open Case] Artifact collection finished.")
            log_callback("[Open Case] Data will be loaded into UI after worker completes...")
            
            # DO NOT load data here - we're in a worker thread!
            # Data loading will happen in the main thread after worker completes
            
            log_callback("[Open Case] Full live artifact collection completed.")
            log_callback("\033[92m[Live Artifacts] All live artifacts have been collected successfully\033[0m")
            
        except Exception as e:
            import traceback
            error_details = traceback.format_exc()
            error_msg = f"Artifact collection failed: {str(e)}"
            log_callback(f"[Error] {error_msg}")
            log_callback(f"[Error Details] {error_details}")
            print(f"[Critical Error] {error_msg}\n{error_details}")
            # Don't raise - allow partial data collection
            # raise

    def parse_all_live_artifacts(self):
        """
        Enhanced live artifact collection with loading dialog.
        
        Bug Fix Task 12.1: Refactored to use LiveAcquisitionWorker instead of QApplication.processEvents().
        """
        # Guard against re-entrancy
        if hasattr(self, '_live_worker') and self._live_worker and self._live_worker.isRunning():
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.warning(
                self.main_window,
                "Analysis In Progress",
                "An artifact collection is already running. Please wait for it to complete."
            )
            return

        # Parsing LIVE Windows artifacts (registry hives, MFT, USN, event logs, ...) reads
        # locked system files that require elevation. If the app isn't running as admin, ask
        # the user to reopen it elevated rather than silently failing.
        try:
            _is_admin = bool(ctypes.windll.shell32.IsUserAnAdmin())
        except Exception:
            _is_admin = False
        if not _is_admin:
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.warning(
                self.main_window,
                "Administrator Rights Required",
                "Parsing live Windows artifacts requires Administrator privileges.\n\n"
                "Please close Crow-Eye and reopen it as Administrator "
                "(right-click → Run as administrator), then try again."
            )
            return

        try:
            # Import the loading dialog and worker
            from ui.Loading_dialog import LoadingDialog
            from ui.gui_workers import LiveAcquisitionWorker
            from PyQt5.QtCore import QEventLoop
            
            # Create enhanced loading dialog
            active_window = QtWidgets.QApplication.activeWindow()
            parent = active_window if active_window else self.main_window
            dialog = LoadingDialog(
                title="CROW EYE SYSTEM",
                parent=parent
            )
            
            # Define the collection steps
            steps = [
                "Initializing artifact collection",
                "Collecting System & User Registry Hives",
                "Extracting data from the registry hive",
                "Collecting LNK (Shortcut) files",
                "Collecting Automatic & Custom Jump Lists",
                "Collecting Prefetch execution evidence",
                "Collecting Windows Event Logs",
                "Collecting ShimCache (AppCompatCache)",
                "Collecting Amcache data",
                "Collecting RecycleBin artifacts",
                "Collecting SRUM network & execution data",
                "Parsing Master File Table (MFT)",
                "Parsing USN Journal",
                "Correlating MFT & USN Data",
                "Loading data into GUI"
            ]
            
            dialog.set_steps(steps)
            dialog.show()
            
            dialog.start_log_capture()
            
            try:
                print("[Open Case] Starting full live analysis...")
                
                # Bug Fix Task 12.1: Architectural Fix using ProcessManager for true parallel execution
                from utils.concurrency.process_manager import Process_Manager
                from utils.concurrency.progress import Progress_Reporter
                from utils.concurrency.standalone_parsers import standalone_collect_live_artifacts
                
                self.process_manager = Process_Manager()
                cancel_event = self.process_manager.manager.Event()
                
                task_handle = self.process_manager.run_parser_task(
                    target_function=standalone_collect_live_artifacts,
                    kwargs={
                        "case_paths": self.case_paths if hasattr(self, 'case_paths') else {},
                        "windows_partition": self.get_windows_partition(),
                        "cancel_event": cancel_event
                    }
                )
                message_queue = task_handle.message_queue
                
                worker = Progress_Reporter(message_queue)
                
                # Connect worker signals to LoadingDialog using QueuedConnection
                worker.simple_progress_updated.connect(dialog.update_step, QtCore.Qt.QueuedConnection)
                worker.log_updated.connect(dialog.add_log_message, QtCore.Qt.QueuedConnection)
                
                # Store dialog reference and connect completion/error signals
                self._live_dialog = dialog
                worker.task_error.connect(self._on_live_acquisition_error, QtCore.Qt.QueuedConnection)
                worker.finished.connect(self._on_live_acquisition_finished, QtCore.Qt.QueuedConnection)

                # Wire the CANCEL button -> the parser's cancel Event so the running
                # collection actually stops (the worker polls is_cancelled(cancel_event)).
                # This connection was previously missing, so Cancel did nothing.
                def _on_cancel_requested(_ce=cancel_event, _pm=self.process_manager):
                    try:
                        _ce.set()
                    except Exception as _e:
                        print(f"[Cancel] Could not set cancel event: {_e}")
                    try:
                        _pm.shutdown()  # terminate the worker process if it doesn't stop soon
                    except Exception as _e:
                        print(f"[Cancel] process_manager shutdown failed: {_e}")
                dialog.cancelled.connect(_on_cancel_requested)

                # Store worker to prevent garbage collection
                self._live_worker = worker

                # Start worker (non-blocking)
                worker.start()
                
            except Exception as e:
                error_msg = f"Artifact collection failed: {str(e)}"
                dialog.add_log_message(f"[Error] {error_msg}")
                print(f"[Error] {error_msg}")
                
                # Keep error dialog open longer
                QtCore.QTimer.singleShot(4000, dialog.close)
                
                # Show error message
                def show_error():
                    QtWidgets.QMessageBox.critical(
                        self.main_window,
                        "Live Artifacts Collection",
                        f"Failed to collect all artifacts: {str(e)}"
                    )
                
                QtCore.QTimer.singleShot(4500, show_error)
                raise
                
            finally:
                dialog.stop_log_capture()
                
        except ImportError:
            print("Warning: Could not load loading dialog, using fallback")
            # Fallback to original implementation
            print("[Open Case] Starting full live analysis...")
            
            # Step 1: Collect all artifacts (without loading data into UI)
            try:
                print("[LNK] Collecting LNK and Jump Lists...")
                from Artifacts_Collectors.A_CJL_LNK_Claw import A_CJL_LNK_Claw
                case_root = self.case_paths.get('case_root') if hasattr(self, 'case_paths') and self.case_paths else None
                A_CJL_LNK_Claw(case_path=case_root, offline_mode=False, direct_parse=True)
            except Exception as e:
                print(f"[LNK Error] {str(e)}")
            try:
                print("[Registry] Collecting live registry data...")
                # Import and call the registry collection function
                from Artifacts_Collectors.Regclaw import parse_live_registry
                case_root = self.case_paths.get('case_root') if hasattr(self, 'case_paths') and self.case_paths else None
                artifacts_dir = self.case_paths.get('artifacts_dir') if hasattr(self, 'case_paths') and self.case_paths else None
                if artifacts_dir:
                    db_path = os.path.join(artifacts_dir, 'registry_data.db')
                else:
                    db_path = None
                parse_live_registry(case_root=case_root, db_path=db_path)
            except Exception as e:
                print(f"[Registry Error] {str(e)}")
            try:
                print("[Prefetch] Collecting prefetch data...")
                from Artifacts_Collectors.Prefetch_claw import process_prefetch_files
                case_root = self.case_paths.get('case_root') if hasattr(self, 'case_paths') and self.case_paths else None
                windows_partition = self.get_windows_partition()
                process_prefetch_files(case_path=case_root, offline_mode=False, windows_partition=windows_partition)
            except Exception as e:
                print(f"[Prefetch Error] {str(e)}")
            try:
                print("[Logs] Collecting Windows event logs...")
                from Artifacts_Collectors.WinLog_Claw import main as collect_logs
                case_root = self.case_paths.get('case_root') if hasattr(self, 'case_paths') and self.case_paths else None
                collect_logs(case_path=case_root)
            except Exception as e:
                print(f"[Logs Error] {str(e)}")
            try:
                print("[ShimCache] Collecting ShimCache data...")
                from Artifacts_Collectors.shimcash_claw import ShimCacheParser
                case_root = self.case_paths.get('case_root') if hasattr(self, 'case_paths') and self.case_paths else None
                artifacts_dir = self.case_paths.get('artifacts_dir') if hasattr(self, 'case_paths') and self.case_paths else None
                if artifacts_dir:
                    db_path = os.path.join(artifacts_dir, 'shimcache.db')
                else:
                    db_path = 'shimcache.db'
                parser = ShimCacheParser(db_path)
                parser.run()
                print("[ShimCache] ShimCache data collected successfully")
            except Exception as e:
                print(f"[ShimCache Error] {str(e)}")
            try:
                print("[SRUM] Collecting SRUM data...")
                from Artifacts_Collectors.SRUM_Claw import parse_srum_data
                artifacts_dir = self.case_paths.get('artifacts_dir') if hasattr(self, 'case_paths') and self.case_paths else None
                if artifacts_dir:
                    windows_partition = self.get_windows_partition()
                    result = parse_srum_data(case_artifacts_dir=artifacts_dir, windows_partition=windows_partition)
                    if result.get('success'):
                        print(f"[SRUM] SRUM data collected successfully: {result.get('statistics', {})}")
                    else:
                        print(f"[SRUM] SRUM parsing completed with warnings: {result.get('errors', [])}")
                else:
                    print("[SRUM] No artifacts directory available, skipping SRUM collection")
            except Exception as e:
                print(f"[SRUM Error] {str(e)}")
            try:
                print("[MFT-USN] Collecting MFT and USN Journal data...")
                self.parse_mft_usn_correlation()
                print("[MFT-USN] MFT and USN Journal data collected successfully")
            except Exception as e:
                print(f"[MFT-USN Error] {str(e)}")
            
            print("[Open Case] Artifact collection finished. Loading data into UI...")
            
            # Step 2: Load all collected data into UI tables
            try:
                self.load_all_data_internal()
            except Exception as e:
                print(f"[Open Case Error] Failed to load data into UI: {str(e)}")
            
            print("[Open Case] Full live analysis and data loading completed.")
    
    def load_all_data(self, loading_dialog=None):
        """Load all data with enhanced loading dialog"""
        try:
            # Import the loading dialog
            from ui.Loading_dialog import LoadingDialog
            
            # Create enhanced loading dialog
            active_window = QtWidgets.QApplication.activeWindow()
            parent = active_window if active_window else self.main_window
            dialog = LoadingDialog(
                title="CROW EYE SYSTEM",
                parent=parent
            )
            
            # Define the steps
            steps = [
                "Loading LNK and Jump List data",
                "Loading Custom Jump Lists", 
                "Loading Registry data",
                "Loading File Activity data",
                "Loading Prefetch data",
                "Loading Event Logs",
                "Loading ShimCache data",
                "Loading Registry Database",
                "Loading Amcache data",
                "Loading RecycleBin data",
                "Loading SRUM data",
                "Loading MFT data",
                "Loading USN Journal data",
                "Loading Correlated MFT-USN data"
            ]
            
            dialog.set_steps(steps)
            dialog.show()
            
            dialog.start_log_capture()
            
            def finalize_loading():
                dialog.close()
                # Ensure main window is reactivated and maximized
                self.main_window.setWindowState(QtCore.Qt.WindowMaximized)
                self.main_window.raise_()
                self.main_window.activateWindow()

            try:
                # Each artifact loader is run independently so that ONE failing
                # artifact is logged and SKIPPED instead of aborting the whole
                # load, and so the Cancel button is honored BETWEEN steps (the
                # loaders run on the GUI thread; processEvents lets the click
                # register, and is_cancelled() is polled each iteration).
                load_steps = [
                    ("LOADING LNK AND JUMP LIST DATA",  self.load_data_from_database_lnkAJL),
                    ("LOADING CUSTOM JUMP LISTS",       self.load_data_from_database_CJL),
                    ("LOADING REGISTRY DATA",           self.load_allReg_data),
                    ("LOADING FILE ACTIVITY DATA",      self.load_files_activity),
                    ("LOADING PREFETCH DATA",           self.load_data_from_Prefetch),
                    ("LOADING EVENT LOGS",              self.load_all_logs),
                    ("LOADING SHIMCACHE DATA",          self.load_shimcache_data),
                    ("LOADING REGISTRY DATABASE",       self.load_registry_data_from_db),
                    ("LOADING AMCACHE DATA",            self.load_amcache_data),
                    ("LOADING RECYCLEBIN DATA",         self.load_recyclebin_data),
                    ("LOADING SRUM DATA",               self.load_srum_data),
                    ("LOADING MFT DATA",                lambda: self.load_mft_data(dialog.add_log_message)),
                    ("LOADING USN JOURNAL DATA",        lambda: self.load_usn_data(dialog.add_log_message)),
                    ("LOADING CORRELATED MFT-USN DATA", lambda: self.load_correlated_data(dialog.add_log_message)),
                ]

                failed = []
                was_cancelled = False
                for idx, (label, loader) in enumerate(load_steps):
                    if dialog.is_cancelled():
                        was_cancelled = True
                        dialog.add_log_message("[Warning] Loading cancelled by user — stopping.")
                        print("[Cancel] Data loading cancelled by user.")
                        break

                    dialog.update_step(idx, label)
                    # Give the event loop a tick so a Cancel click registers and
                    # the UI repaints before the (synchronous) loader runs.
                    QtWidgets.QApplication.processEvents()

                    print(f"[{label}] Starting...")
                    try:
                        loader()
                        print(f"[{label}] Completed.")
                    except Exception as e:
                        failed.append(label)
                        dialog.add_log_message(f"[Error] {label} failed — skipping: {e}")
                        print(f"[Error] {label} failed — skipping: {e}")
                        continue

                # End-state: cancelled / partial (some skipped) / full success.
                if was_cancelled:
                    dialog.add_log_message("[Warning] Operation cancelled — partial data loaded.")
                    QtCore.QTimer.singleShot(1200, finalize_loading)
                elif failed:
                    dialog.add_log_message(
                        f"[Warning] {len(failed)} artifact(s) skipped: {', '.join(failed)}")
                    dialog.show_completion(
                        f"DATA LOADED — {len(failed)} artifact(s) skipped")
                    print(f"\033[93m\nData loaded with {len(failed)} artifact(s) skipped: "
                          f"{', '.join(failed)}\033[0m")
                    QtCore.QTimer.singleShot(2000, finalize_loading)
                else:
                    dialog.show_completion("ALL DATA LOADED SUCCESSFULLY")
                    print("\033[92m\nData has been loaded into the GUI Successfully\033[0m")
                    QtCore.QTimer.singleShot(2000, finalize_loading)

            except Exception as e:
                error_msg = f"Error loading data: {str(e)}"
                dialog.add_log_message(f"[Error] {error_msg}")
                print(f"[Error] {error_msg}")
                QtWidgets.QApplication.processEvents()
                
                # Keep error dialog open longer
                QtCore.QTimer.singleShot(4000, dialog.close)
                raise
                
            finally:
                dialog.stop_log_capture()
                
        except ImportError:
            print("Warning: Could not load loading dialog, using fallback")
            # Fallback to existing implementation
            if loading_dialog:
                self.load_all_data_with_progress(loading_dialog)
            else:
                self.run_analysis_with_loading("Loading All Data...", self.load_all_data_internal, run_in_thread=True)
    
